// ==================== Actions ====================
async function handleExportXml() {
  if (!currentXml.value) {
    ElMessage.warning('请先设计流程')
    return
  }
  const blob = new Blob([currentXml.value], { type: 'application/xml' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `${deployForm.value.flowCode || 'process'}.bpmn`
  a.click()
  URL.revokeObjectURL(url)
  ElMessage.success('BPMN XML 已导出')
}

/**
 * P1: 导出流程图为 SVG 文件
 *
 * <p>对标钉钉/飞书审批流设计器，支持将流程图导出为 SVG 矢量图，用于文档归档。
 * bpmn-js 的 saveSVG 结果已缓存在 currentSvg，直接下载即可。
 */
async function handleExportSvg() {
  if (!currentSvg.value) {
    ElMessage.warning('请先设计流程')
    return
  }
  const blob = new Blob([currentSvg.value], { type: 'image/svg+xml' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `${deployForm.value.flowCode || 'process'}.svg`
  a.click()
  URL.revokeObjectURL(url)
  ElMessage.success('流程图 SVG 已导出')
}

/**
 * P1: 导出流程图为 PNG 文件
 *
 * <p>将 SVG 转为 Canvas 再导出 PNG，适用于非矢量场景的截图分享。
 * 通过 Image 加载 SVG data URL → drawImage 到 canvas → toDataURL('image/png') 下载。
 */
async function handleExportPng() {
  if (!currentSvg.value) {
    ElMessage.warning('请先设计流程')
    return
  }
  try {
    const svgDataUrl = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(currentSvg.value)
    const img = new Image()
    img.onload = () => {
      const canvas = document.createElement('canvas')
      canvas.width = img.naturalWidth || img.width
      canvas.height = img.naturalHeight || img.height
      const ctx = canvas.getContext('2d')
      if (!ctx) {
        ElMessage.error('Canvas 2D 上下文不可用，无法导出 PNG')
        return
      }
      ctx.fillStyle = '#ffffff'
      ctx.fillRect(0, 0, canvas.width, canvas.height)
      ctx.drawImage(img, 0, 0)
      canvas.toBlob((blob) => {
        if (!blob) {
          ElMessage.error('PNG 生成失败')
          return
        }
        const url = URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = url
        a.download = `${deployForm.value.flowCode || 'process'}.png`
        a.click()
        URL.revokeObjectURL(url)
        ElMessage.success('流程图 PNG 已导出')
      }, 'image/png')
    }
    img.onerror = () => {
      ElMessage.error('SVG 加载失败，无法导出 PNG')
    }
    img.src = svgDataUrl
  } catch (e) {
    ElMessage.error('PNG 导出失败：' + (e as Error).message)
  }
}

async function handleImportXml() {
  const input = document.createElement('input')
  input.type = 'file'
  input.accept = '.bpmn,.xml'
  input.onchange = async (e: Event) => {
    const file = (e.target as HTMLInputElement).files?.[0]
    if (!file) return
    const text = await file.text()
    await loadXml(text)
    ElMessage.success('BPMN XML 已导入')
  }
  input.click()
}

async function handleSave() {
  if (!currentXml.value) {
    ElMessage.warning('请先设计流程')
    return
  }
  saving.value = true
  try {
    emit('save', currentXml.value, currentSvg.value)
    ElMessage.success('流程已保存')
  } finally {
    saving.value = false
  }
}

async function handleDeploy() {
  if (!currentXml.value) {
    ElMessage.warning('请先设计流程')
    return
  }
  if (!deployForm.value.flowCode.trim()) {
    ElMessage.warning('请输入流程编码')
    return
  }
  if (!deployForm.value.flowName.trim()) {
    ElMessage.warning('请输入流程名称')
    return
  }
  saving.value = true
  try {
    const payload: FlowDeployDTO = {
      flowCode: deployForm.value.flowCode.trim(),
      flowName: deployForm.value.flowName.trim(),
      category: deployForm.value.category,
      formPath: deployForm.value.formPath,
      bpmnXml: currentXml.value,
    }
    const res = await deployDefinition(payload)
    if (res.data?.code === 0) {
      ElMessage.success(`流程部署成功，定义 ID: ${res.data.data}`)
      emit('deploy', deployForm.value.flowCode, deployForm.value.flowName, currentXml.value)
    } else {
      ElMessage.error(res.data?.message || '部署失败')
    }
  } catch (e) {
    ElMessage.error('部署失败：' + (e as Error).message)
  } finally {
    saving.value = false
  }
}

function handleReset() {
  loadBlankDiagram()
  ElMessage.success('已重置为空白流程')
}

/**
 * P2-3: 一键自动布局（dagre 分层有向图）
 *
 * <p>解决 bpmn-js 内置 BpmnAutoPlace 对网关分叉/并行汇聚场景节点重叠、连线交叉的问题。
 * 用户点击按钮触发，不破坏手动调整结果；坐标通过 moveShape 写入 BPMNDI 段，
 * 部署后实例详情/回放均能透传。
 */
function handleAutoLayout() {
  if (!modeler.value) return
  try {
    autoLayout(modeler.value)
    ElMessage.success('已自动布局')
  } catch (e) {
    ElMessage.error('自动布局失败：' + (e as Error).message)
  }
}

/**
 * P2-5: 画布缩放与适配视图
 *
 * <p>对标钉钉/飞书审批流设计器，提供放大/缩小/适配画布三件套。
 * 基于 bpmn-js 内置 zoomScroll 与 canvas 服务，无需额外依赖。
 */
function handleZoomIn() {
  if (!modeler.value) return
  // bpmn-js 的 get() 返回 unknown，用类型断言收敛
  const zoomScroll = modeler.value.get('zoomScroll') as { stepZoom: (step: number) => void }
  zoomScroll.stepZoom(1)
}

function handleZoomOut() {
  if (!modeler.value) return
  const zoomScroll = modeler.value.get('zoomScroll') as { stepZoom: (step: number) => void }
  zoomScroll.stepZoom(-1)
}

function handleFitView() {
  if (!modeler.value) return
  const canvas = modeler.value.get('canvas') as { zoom: (level: string | number, position?: string) => void }
  canvas.zoom('fit-viewport', 'auto')
}

