    <bpmn:sequenceFlow id="Flow_3" sourceRef="Gateway_Split" targetRef="Task_Finance"/>
    <bpmn:sequenceFlow id="Flow_4" sourceRef="Gateway_Split" targetRef="Task_Biz"/>
    <bpmn:sequenceFlow id="Flow_5" sourceRef="Task_Legal" targetRef="Gateway_Join"/>
    <bpmn:sequenceFlow id="Flow_6" sourceRef="Task_Finance" targetRef="Gateway_Join"/>
    <bpmn:sequenceFlow id="Flow_7" sourceRef="Task_Biz" targetRef="Gateway_Join"/>
    <bpmn:sequenceFlow id="Flow_8" sourceRef="Gateway_Join" targetRef="Task_CEO"/>
    <bpmn:sequenceFlow id="Flow_9" sourceRef="Task_CEO" targetRef="EndEvent_1"/>
  </bpmn:process>
</bpmn:definitions>`,
  },
]

function applyTemplate(tpl: (typeof templates)[0]) {
  if (!tpl.xml) {
    loadBlankDiagram()
  } else {
    loadXml(tpl.xml)
  }
  ElMessage.success(`已加载模板：${tpl.label}`)
}
</script>

<template>
  <div class="bpmn-designer">
