          <span>正在加载 BPMN 设计器...</span>
        </div>
      </div>

      <!-- P1-02: 自定义属性面板 -->
      <div class="bpmn-property-panel">
        <div v-if="!selectedElement" class="panel-empty">
          <el-empty description="选择一个元素查看属性" :image-size="60" />
        </div>

        <template v-else>
