                />
              </el-form-item>
            </template>
          </el-form>
        </template>
      </div>
    </div>

    <!-- 部署面板 -->
    <div class="bpmn-deploy-bar">
      <el-input
        v-model="deployForm.flowCode"
        placeholder="流程编码（如 project_initiation）"
